import os
tomllib = __import__('tomllib')

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        with open(toml_path, 'rb') as f:
            toml_config = tomllib.load(f)
            config.update(toml_config)
    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            nested_key = key[len(env_prefix):].replace('__', '.').lower()
            set_nested(config, nested_key, value)
    return config

def set_nested(d, keys, value):
    keys = keys.split('.')
    for key in keys[:-1]:
        d = d.setdefault(key, {})
    d[keys[-1]] = value

import pytest
from envcfg import load_config, ConfigError

def test_load_defaults():
    defaults = {'a': 1, 'b': 'two'}
    assert load_config(defaults) == defaults

def test_load_toml():
    defaults = {'a': 1, 'b': 'two'}
    with open('config.toml', 'w') as f:
        f.write('a = 2\nb = "three"')
    config = load_config(defaults, 'config.toml')
    assert config == {'a': 2, 'b': 'three'}

def test_load_env():
    defaults = {'a': 1, 'b': 'two'}
    os.environ['APP__A'] = '3'
    os.environ['APP__B'] = 'four'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'a': 3, 'b': 'four'}

def test_load_env_nested():
    defaults = {'server': {'port': 8080}}
    os.environ['APP__SERVER__PORT'] = '8081'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'server': {'port': 8081}}

def test_load_env_coercion():
    defaults = {'a': 1, 'b': True}
    os.environ['APP__A'] = '2'
    os.environ['APP__B'] = 'false'
    config = load_config(defaults, env_prefix='APP__')
    assert config == {'a': 2, 'b': False}

def test_load_env_error():
    defaults = {'a': 1}
    os.environ['APP__A'] = 'two'
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__')

def test_load_env_missing_default():
    defaults = {'a': 1}
    os.environ['APP__B'] = 'two'
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__')

